  box-shadow: var(--shadow-md);
  background: var(--white);
}

.featured-thumbnail {
  width: 100%;
  aspect-ratio: 2/1;
  overflow: hidden;
}

.featured-thumbnail svg {
  width: 100%;
  height: 100%;
}

.featured-content {
  padding: 24px;
}

.featured-title {
  font-size: 28px;
  font-weight: 800;
  line-height: 1.3;
  margin: 10px 0 16px;
  color: var(--text);
}

/* Tags */
