/* Article meta */
.article-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--text-muted);
}

.author-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 10px;
  font-weight: 700;
  flex-shrink: 0;
}

.meta-separator {
  color: var(--gray-400);
}

/* Section Title */
.section-title {
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 24px;
  color: var(--text);
}

/* Article Grid */
.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

@media (max-width: 900px) {
  .article-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 580px) {
  .article-grid { grid-template-columns: 1fr; }
  .featured-title { font-size: 22px; }
}

.article-card {
  background: var(--white);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
  transition: transform var(--transition), box-shadow var(--transition);
}

.article-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.card-thumbnail {
  aspect-ratio: 16/10;
  overflow: hidden;
}

.card-thumbnail svg {
  width: 100%;
  height: 100%;
}

.card-body {
  padding: 16px;
}

.card-title {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.4;
  margin: 8px 0 12px;
  color: var(--text);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* Load More */
.load-more-container {
  text-align: center;
  margin-top: 36px;
}

.load-more-btn {
  background: var(--primary);
  color: var(--white);
  border: none;
  padding: 12px 36px;
  font-size: 15px;
  font-weight: 600;
  border-radius: 6px;
  cursor: pointer;
  font-family: inherit;
  transition: var(--transition);
}

.load-more-btn:hover {
  background: #1a1a4e;
}

.load-more-btn.disabled {
  background: var(--gray-400);
  cursor: default;
}

/* ============================================
   Footer
   ============================================ */

.site-footer {
  background: var(--primary);
  color: rgba(255,255,255,0.7);
  padding: 48px 24px;
  margin-top: 48px;
}

.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
}

.footer-mission {
  font-size: 14px;
  line-height: 1.7;
  margin-bottom: 28px;
  max-width: 720px;
}

.footer-guides h4 {
  color: var(--white);
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 10px;
}

.guide-links {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 24px;
}

.guide-links a {
  color: var(--accent);
  font-size: 13px;
  font-weight: 500;
  padding: 4px 10px;
  border: 1px solid rgba(254,172,50,0.25);
  border-radius: 4px;
  transition: var(--transition);
}

.guide-links a:hover {
  background: rgba(254,172,50,0.1);
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 16px;
  padding-top: 20px;
  border-top: 1px solid rgba(255,255,255,0.1);
}

.footer-links a {
  color: rgba(255,255,255,0.55);
  font-size: 13px;
  transition: var(--transition);
}

.footer-links a:hover {
  color: var(--white);
}

/* ============================================
   Learn Page
   ============================================ */

.learn-page {
  max-width: 900px;
  margin: 0 auto;
  padding: 40px 24px 48px;
}

.welcome-box {
  background: var(--light-bg);
  border-radius: var(--radius);
  padding: 28px;
  margin-bottom: 40px;
  text-align: center;
}

.welcome-box p {
  font-size: 16px;
  color: var(--text-muted);
  margin-bottom: 16px;
}

.welcome-box .btn-primary {
  background: var(--accent);
  color: var(--primary);
  border: none;
  padding: 10px 28px;
  font-size: 15px;
  font-weight: 700;
  border-radius: 6px;
  cursor: pointer;
  font-family: inherit;
  display: inline-block;
}

.curriculum-section {
  margin-bottom: 40px;
}

.curriculum-section h2 {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 16px;
  color: var(--text);
  display: flex;
  align-items: center;
  gap: 10px;
}

.curriculum-list {
  list-style: none;
}

.curriculum-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  border-radius: 6px;
  transition: var(--transition);
  border: 1px solid var(--gray-200);
  margin-bottom: 8px;
  cursor: pointer;
}

.curriculum-item:hover {
  background: var(--light-bg);
  border-color: var(--accent);
}

.curriculum-icon {
  width: 40px;
  height: 40px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  flex-shrink: 0;
}

.curriculum-item-text {
  font-weight: 600;
  font-size: 15px;
}

.curriculum-item-sub {
  font-size: 13px;
  color: var(--text-muted);
  margin-top: 2px;
}

/* Daily Challenge */
.challenge-box {
  background: linear-gradient(135deg, #0a0a23, #1a1a4e);
  border-radius: var(--radius);
  padding: 28px;
  color: var(--white);
  margin-bottom: 40px;
}

.challenge-box h3 {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 16px;
}

.challenge-links {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.challenge-link {
  background: var(--accent);
  color: var(--primary);
  padding: 8px 20px;
  border-radius: 6px;
  font-weight: 600;
  font-size: 14px;
  transition: var(--transition);
}

.challenge-link:hover {
  opacity: 0.9;
}

.challenge-link.secondary {
  background: rgba(255,255,255,0.12);
  color: var(--white);
}

.challenge-link.secondary:hover {
  background: rgba(255,255,255,0.2);
}

/* Prep section */
.prep-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 20px;
  margin-bottom: 40px;
}

.prep-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius);
  padding: 20px;
}

.prep-card h3 {
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 12px;
  color: var(--text);
}

.prep-card ul {
  list-style: none;
}

.prep-card li {
  padding: 6px 0;
  font-size: 14px;
  color: var(--link-blue);
  cursor: pointer;
}

.prep-card li:hover {
  text-decoration: underline;
}

/* ============================================
   Donate Page
   ============================================ */

.donate-hero {
  background: linear-gradient(135deg, #0a0a23 0%, #1a1a4e 100%);
  padding: 60px 24px;
  text-align: center;
  color: var(--white);
}

.donate-hero h1 {
  font-size: 36px;
  font-weight: 800;
  margin-bottom: 16px;
}

.donate-hero p {
  max-width: 640px;
  margin: 0 auto;
  font-size: 16px;
  line-height: 1.7;
  color: rgba(255,255,255,0.8);
}

.donate-form-section {
  max-width: 560px;
  margin: -30px auto 40px;
  padding: 0 24px;
  position: relative;
  z-index: 10;
}

.donate-card {
  background: var(--white);
  border-radius: 12px;
  padding: 32px;
  box-shadow: var(--shadow-md);
  text-align: center;
}

.amount-tabs {
  display: flex;
  gap: 8px;
  justify-content: center;
  margin-bottom: 20px;
}

.amount-tab {
  padding: 10px 24px;
  border: 2px solid var(--gray-300);
  border-radius: 8px;
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
  background: var(--white);
  font-family: inherit;
  transition: var(--transition);
  color: var(--text);
}

.amount-tab.active {
  border-color: var(--accent);
  background: #fff8e6;
  color: var(--primary);
}

.amount-tab:hover:not(.active) {
  border-color: var(--gray-400);
}

.donate-description {
  font-size: 15px;
  color: var(--text-muted);
  margin-bottom: 20px;
  line-height: 1.6;
}

.donate-btn {
  background: var(--accent);
  color: var(--primary);
  border: none;
  padding: 14px 48px;
  font-size: 18px;
  font-weight: 800;
  border-radius: 8px;
  cursor: pointer;
  font-family: inherit;
  transition: var(--transition);
  width: 100%;
}

.donate-btn:hover {
  opacity: 0.9;
  transform: translateY(-1px);
}

.donate-sub {
  font-size: 13px;
  color: var(--text-muted);
  margin-top: 12px;
}

.donate-sub a {
  color: var(--link-blue);
}

/* Benefits & Sections */
.donate-content {
  max-width: 800px;
  margin: 0 auto;
  padding: 0 24px 48px;
}

.donate-section {
  margin-bottom: 40px;
}

.donate-section h2 {
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 16px;
  color: var(--text);
}

.benefits-list, .initiatives-list, .achievements-list {
  list-style: none;
}

.benefits-list li, .initiatives-list li, .achievements-list li {
  padding: 10px 0;
  font-size: 15px;
  line-height: 1.6;
  border-bottom: 1px solid var(--gray-200);
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.benefits-list li::before {
  content: "\2713";
  color: #00b894;
  font-weight: 700;
  flex-shrink: 0;
}

.initiatives-list li::before {
  content: "\2192";
  color: var(--accent);
  font-weight: 700;
  flex-shrink: 0;
}

.achievements-list li::before {
  content: "\2605";
  color: var(--accent);
  font-weight: 700;
  flex-shrink: 0;
}

/* FAQ Accordion */
.faq-section h2 {
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 16px;
  color: var(--text);
}

.faq-item {
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  margin-bottom: 8px;
  overflow: hidden;
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  background: var(--white);
  cursor: pointer;
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  border: none;
  width: 100%;
  text-align: left;
  font-family: inherit;
  transition: var(--transition);
}

.faq-question:hover {
  background: var(--gray-100);
}

.faq-chevron {
  width: 20px;
  height: 20px;
  transition: transform 0.3s ease;
  flex-shrink: 0;
  color: var(--gray-500);
}

.faq-item.open .faq-chevron {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
}

.faq-item.open .faq-answer {
  max-height: 200px;
}

.faq-answer-inner {
  padding: 0 20px 16px;
  font-size: 14px;
  line-height: 1.7;
  color: var(--text-muted);
}

/* ============================================
   Tag Pages
   ============================================ */

.tag-header {
  text-align: center;
  padding: 40px 24px 20px;
}

.tag-header h1 {
  font-size: 32px;
  font-weight: 800;
  color: var(--text);
  text-transform: uppercase;
}

.tag-header .post-count {
  font-size: 15px;
  color: var(--text-muted);
  margin-top: 4px;
}

.popular-tags {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px 32px;
}

.popular-tags h3 {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 12px;
}

.tags-row {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 8px;
  scrollbar-width: thin;
}

.tags-row::-webkit-scrollbar {
  height: 4px;
}

.tags-row::-webkit-scrollbar-thumb {
  background: var(--gray-300);
  border-radius: 4px;
}

.popular-tag {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border: 1px solid var(--gray-200);
  border-radius: 20px;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  transition: var(--transition);
  flex-shrink: 0;
}

.popular-tag:hover {
  border-color: var(--accent);
  background: #fff8e6;
}

.popular-tag .count {
  color: var(--text-muted);
  font-size: 12px;
}

.tag-page-content {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px 48px;
}
